package medicalsecure;

import org.jcodec.api.awt.AWTSequenceEncoder;
import java.awt.*;import java.awt.geom.*;import java.awt.image.BufferedImage;import java.nio.file.Path;

public final class VideoRenderer {
    public interface Progress{void update(int frame,int total,String scene);} private static final int W=1280,H=720,FPS=12,SECONDS=150;
    public static Path render(Path output,String fileName,boolean suspicious,Progress p)throws Exception{
        AWTSequenceEncoder enc=AWTSequenceEncoder.createSequenceEncoder(output.toFile(),FPS);int total=FPS*SECONDS;
        for(int f=0;f<total;f++){double t=f/(double)FPS;enc.encodeImage(frame(t,f,fileName,suspicious));if(p!=null&&(f%FPS==0||f==total-1))p.update(f+1,total,scene(t));}enc.finish();return output;
    }
    private static String scene(double t){if(t<15)return"SECURITY CONTROL CENTER";if(t<32)return"FILE SELECTED BY USER";if(t<50)return"THREAT ANALYSIS";if(t<72)return"AES-256-GCM ENCRYPTION";if(t<94)return"RSA KEY PROTECTION";if(t<114)return"SECURE MEDICAL EXCHANGE";if(t<130)return"INTEGRITY + SIGNATURE VERIFICATION";if(t<142)return"SUSPICIOUS FILE BLOCK + QUARANTINE";return"FINAL SECURITY DECISION";}
    private static BufferedImage frame(double t,int f,String file,boolean bad){BufferedImage b=new BufferedImage(W,H,BufferedImage.TYPE_3BYTE_BGR);Graphics2D g=b.createGraphics();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);g.setPaint(new GradientPaint(0,0,new Color(5,14,31),W,H,new Color(29,8,47)));g.fillRect(0,0,W,H);grid(g,f);text(g,"MEDCRYPT SENTINEL  //  HEALTHCARE SECURITY OPERATIONS CENTER",35,42,27,Color.WHITE,true);pill(g,"LIVE CRYPTOGRAPHIC DEMO",1015,18,230,34,new Color(32,205,160));
        if(t<15)intro(g,t);else if(t<32)selected(g,t,file);else if(t<50)analysis(g,t,file,bad);else if(t<72)encrypt(g,t,file);else if(t<94)keys(g,t);else if(t<114)exchange(g,t);else if(t<130)verify(g,t);else if(t<142)quarantine(g,t,file,bad);else finale(g,bad,file);footer(g,scene(t),f);g.dispose();return b;}
    private static void intro(Graphics2D g,double t){big(g,"MEDICAL DATA",70,190,65,Color.WHITE);big(g,"DESERVES",70,260,65,new Color(70,220,180));big(g,"CRYPTOGRAPHIC TRUST",70,330,65,Color.WHITE);text(g,"Confidentiality  •  Integrity  •  Authenticity  •  Threat Defense",75,385,23,new Color(185,205,230),false);card(g,720,140,420,300);String[] a={"AES-256-GCM","RSA-2048 / OAEP","SHA-256","RSA DIGITAL SIGNATURE","REPLAY DEFENSE"};for(int i=0;i<a.length;i++){dot(g,755,190+i*45,new Color(65,210,180));text(g,a[i],780,197+i*45,20,Color.WHITE,true);}pulse(g,920,510,t);}
    private static void selected(Graphics2D g,double t,String file){label(g,"USER CONTROLLED FILE SELECTION",65,125);card(g,65,150,1150,430);fileIcon(g,135,235);text(g,"SELECTED FROM YOUR DOCUMENTS",285,220,18,new Color(140,165,195),true);text(g,trim(file,38),285,275,32,Color.WHITE,true);text(g,"The application processes the actual document chosen by the user.",285,320,20,new Color(190,210,230),false);pill(g,"FILE LOCKED INTO ANALYSIS PIPELINE",375,420,530,48,new Color(38,190,160));network(g,140,530,1140,530,t,0);}
    private static void analysis(Graphics2D g,double t,String file,boolean bad){label(g,"FILE SECURITY ANALYSIS",65,125);card(g,65,150,1150,430);text(g,trim(file,35),105,210,28,Color.WHITE,true);String[] rows=bad?new String[]{"Suspicious content pattern","Unexpected command indicator","Risk threshold exceeded","SECURE EXCHANGE BLOCKED"}:new String[]{"File structure inspected","Content indicators checked","SHA-256 fingerprint generated","READY FOR CRYPTOGRAPHIC PROTECTION"};for(int i=0;i<rows.length;i++){boolean x=bad&&i<3;circle(g,145,280+i*55,x?new Color(245,75,90):new Color(55,220,170));text(g,(x?"ALERT  ":"PASS   ")+rows[i],180,287+i*55,22,x?new Color(255,115,125):Color.WHITE,true);}pill(g,bad?"RISK DECISION: SUSPICIOUS":"RISK DECISION: SAFE",420,490,440,50,bad?new Color(225,65,90):new Color(35,195,155));}
    private static void encrypt(Graphics2D g,double t,String file){label(g,"AES-256-GCM ENCRYPTION",65,125);card(g,65,150,1150,430);text(g,"PLAINTEXT MEDICAL RECORD",110,220,22,new Color(165,190,215),true);text(g,trim(file,30),110,260,28,Color.WHITE,true);lock(g,250,350);for(int i=0;i<14;i++){double p=((t-50)/22+i*.07)%1;packet(g,430+p*330,375,i);}lock(g,930,350);text(g,"CIPHERTEXT",895,450,20,new Color(65,220,180),true);meter(g,100,520,1070,(t-50)/22,"ENCRYPTION PROGRESS");}
    private static void keys(Graphics2D g,double t){label(g,"HYBRID KEY PROTECTION",65,125);card(g,65,150,1150,430);lock(g,160,260);text(g,"AES SESSION KEY",275,275,27,Color.WHITE,true);arrow(g,440,280,690,280,(t-72)/22);lock(g,735,245);text(g,"RSA-2048 + OAEP",830,275,29,new Color(190,125,255),true);text(g,"Only the authorized receiver can unwrap the AES key.",275,355,21,new Color(190,210,230),false);node(g,220,490,"SENDER");node(g,640,490,"SECURE KEY");node(g,1040,490,"RECEIVER");}
    private static void exchange(Graphics2D g,double t){label(g,"SECURE MEDICAL EXCHANGE",65,125);card(g,65,150,1150,430);node(g,170,330,"HOSPITAL A");node(g,1110,330,"DOCTOR B");for(int i=0;i<10;i++){double p=((t-94)/20+i*.1)%1;packet(g,270+p*780,330,i);}text(g,"Encrypted packets only • no plaintext on the wire",355,465,24,Color.WHITE,true);pill(g,"SECURE CHANNEL ACTIVE",450,515,380,45,new Color(35,195,155));}
    private static void verify(Graphics2D g,double t){label(g,"INTEGRITY + AUTHENTICITY",65,125);card(g,65,150,1150,430);text(g,"SHA-256",120,245,34,new Color(255,195,70),true);text(g,"FINGERPRINT",120,285,18,Color.WHITE,true);text(g,"a8f3…9c21",120,320,25,Color.WHITE,false);arrow(g,360,280,530,280,(t-114)/16);text(g,"RSA DIGITAL SIGNATURE",570,245,30,new Color(190,125,255),true);text(g,"SIGNATURE CHECK",570,285,18,Color.WHITE,true);arrow(g,820,280,965,280,(t-114)/16);check(g,1030,290);pill(g,"VERIFIED • AUTHENTIC • INTACT",390,490,500,50,new Color(35,195,155));}
    private static void quarantine(Graphics2D g,double t,String file,boolean bad){label(g,"THREAT RESPONSE",65,125);card(g,65,150,1150,430);text(g,trim(file,32),100,215,28,Color.WHITE,true);if(bad){node(g,190,350,"FILE");arrow(g,290,350,465,350,1);node(g,560,350,"BLOCK");arrow(g,660,350,835,350,1);node(g,930,350,"QUARANTINE");text(g,"No encryption. No exchange. No authorized release.",250,470,23,new Color(255,180,190),false);pill(g,"🚨 SECURE EXCHANGE BLOCKED",410,515,460,45,new Color(225,65,90));}else{check(g,640,350);text(g,"Safe scenario completes secure exchange.",430,470,23,Color.WHITE,false);pill(g,"SAFE PATH",520,515,240,45,new Color(35,195,155));}}
    private static void finale(Graphics2D g,boolean bad,String file){label(g,"FINAL SECURITY DECISION",65,125);card(g,65,150,1150,430);text(g,"FILE: "+trim(file,40),110,210,23,Color.WHITE,true);pill(g,"SAFE PATH",120,265,260,44,new Color(35,195,155));text(g,"Encrypt  →  Exchange  →  Verify  →  Decrypt",430,294,22,Color.WHITE,true);pill(g,"SUSPICIOUS PATH",120,365,300,44,new Color(225,65,90));text(g,"Detect  →  Block  →  Quarantine  →  Report",460,394,22,Color.WHITE,true);text(g,"CONFIDENTIALITY   ✓     INTEGRITY   ✓     AUTHENTICITY   ✓",250,500,25,new Color(80,225,190),true);text(g,"MEDICAL DATA SECURITY DEMONSTRATION COMPLETE",335,550,20,Color.WHITE,true);}
    private static void grid(Graphics2D g,int f){g.setColor(new Color(255,255,255,10));for(int x=0;x<W;x+=40)g.drawLine(x,0,x,H);for(int y=0;y<H;y+=40)g.drawLine(0,y,W,y);}
    private static void card(Graphics2D g,int x,int y,int w,int h){g.setColor(new Color(255,255,255,18));g.fillRoundRect(x,y,w,h,24,24);g.setColor(new Color(100,180,230,35));g.drawRoundRect(x,y,w,h,24,24);}
    private static void text(Graphics2D g,String s,int x,int y,int z,Color c,boolean bold){g.setColor(c);g.setFont(new Font("SansSerif",bold?Font.BOLD:Font.PLAIN,z));g.drawString(s,x,y);}private static void big(Graphics2D g,String s,int x,int y,int z,Color c){text(g,s,x,y,z,c,true);}private static void label(Graphics2D g,String s,int x,int y){text(g,s,x,y,16,new Color(120,205,230),true);}
    private static void pill(Graphics2D g,String s,int x,int y,int w,int h,Color c){g.setColor(c);g.fillRoundRect(x,y,w,h,h,h);text(g,s,x+18,y+29,15,Color.WHITE,true);}private static void dot(Graphics2D g,int x,int y,Color c){g.setColor(c);g.fillOval(x-6,y-6,12,12);}private static void circle(Graphics2D g,int x,int y,Color c){g.setColor(c);g.fillOval(x-12,y-12,24,24);}
    private static void lock(Graphics2D g,int x,int y){g.setColor(new Color(90,220,190));g.setStroke(new BasicStroke(4));g.drawRoundRect(x,y,70,60,12,12);g.drawArc(x+15,y-35,40,50,0,180);g.fillOval(x+31,y+25,8,18);}private static void check(Graphics2D g,int x,int y){g.setColor(new Color(55,230,175));g.setStroke(new BasicStroke(7));g.drawOval(x-45,y-45,90,90);g.drawLine(x-25,y,x-5,y+20);g.drawLine(x-5,y+20,x+30,y-25);}private static void node(Graphics2D g,int x,int y,String s){g.setColor(new Color(50,120,210,120));g.fillOval(x-45,y-45,90,90);text(g,s,x-42,y+72,14,Color.WHITE,true);}private static void arrow(Graphics2D g,int x1,int y1,int x2,int y2,double p){g.setColor(new Color(70,190,230));g.setStroke(new BasicStroke(4));g.drawLine(x1,y1,x2,y2);double q=Math.max(0,Math.min(1,p));double x=x1+(x2-x1)*q;double y=y1+(y2-y1)*q;g.fillOval((int)x-9,(int)y-9,18,18);}private static void packet(Graphics2D g,double x,double y,int i){g.setColor(new Color(65,215,180,210));g.fillRoundRect((int)x-14,(int)y-9,28,18,7,7);}private static void network(Graphics2D g,int x1,int y1,int x2,int y2,double t,int off){g.setColor(new Color(50,170,220,120));g.drawLine(x1,y1,x2,y2);for(int i=0;i<8;i++){double q=((t/2)+i*.13)%1;packet(g,x1+q*(x2-x1),y1, i);}}private static void meter(Graphics2D g,int x,int y,int w,double p,String s){label(g,s,x,y-18);g.setColor(new Color(255,255,255,40));g.drawRoundRect(x,y,w,18,18,18);g.setColor(new Color(45,210,170));g.fillRoundRect(x,y,(int)(w*Math.max(0,Math.min(1,p))),18,18,18);}private static void pulse(Graphics2D g,int x,int y,double t){g.setColor(new Color(60,210,180,100));for(int i=0;i<5;i++){int r=25+i*28+(int)((t*18)%25);g.drawOval(x-r,y-r,r*2,r*2);}}
    private static void fileIcon(Graphics2D g,int x,int y){g.setColor(new Color(75,190,240));g.setStroke(new BasicStroke(4));g.drawRoundRect(x,y,100,125,12,12);g.drawLine(x+65,y,x+100,y+35);g.drawLine(x+65,y,x+65,y+35);}private static void footer(Graphics2D g,String s,int f){text(g,s,35,682,16,new Color(150,175,205),true);text(g,String.format("FRAME %05d  •  %ds  •  MEDCRYPT LAB",f,f/FPS),955,682,13,new Color(130,150,180),false);}private static String trim(String s,int n){return s==null?"":s.length()>n?s.substring(0,n-3)+"...":s;}
}
